          <div className="mt-3 sm:mt-4 flex items-center gap-3">
            <span className="text-4xl sm:text-5xl drop-shadow-sm animate-float">{moodEmoji[currentMood] || '😊'}</span>
            <span className={`text-xl sm:text-2xl font-bold ${darkMode ? 'text-slate-100' : 'text-slate-800'}`}>{t(moodLabelKey[currentMood] || 'happy', language)}</span>
